use async_trait::async_trait;
use serde_json::{json, Value};
use std::{collections::HashMap, process::Command, sync::Arc};
use tracing::{error, info};

use crate::tool::{Tool, ToolDefinition, ToolParameter, ToolParameterType};

pub struct IndexerSearchTool;

#[async_trait]
impl Tool for IndexerSearchTool {
    fn name(&self) -> &str {
        "indexer_search"
    }

    fn description(&self) -> &str {
        "Searches the OpenClaw code index semantically for relevant code snippets."
    }

    fn parameters(&self) -> Option<ToolDefinition> {
        Some(ToolDefinition {
            name: self.name().to_string(),
            description: self.description().to_string(),
            parameters: vec![
                ToolParameter {
                    name: "query".to_string(),
                    description: "The semantic query string to search for.".to_string(),
                    param_type: ToolParameterType::String,
                    required: true,
                },
                ToolParameter {
                    name: "repo".to_string(),
                    description: "Optional: Filter search results by repository name.".to_string(),
                    param_type: ToolParameterType::String,
                    required: false,
                },
                ToolParameter {
                    name: "language".to_string(),
                    description: "Optional: Filter search results by programming language.".to_string(),
                    param_type: ToolParameterType::String,
                    required: false,
                },
                ToolParameter {
                    name: "limit".to_string(),
                    description: "Optional: Maximum number of results to return (default: 5).".to_string(),
                    param_type: ToolParameterType::Number,
                    required: false,
                },
            ],
            // Assuming `plugin_type` for the Indexer search tool would be "custom" or similar.
            // This might need to be refined based on op-dbus plugin types.
            plugin_type: Some("custom".to_string()),
        })
    }

    async fn execute(&self, args: HashMap<String, Value>) -> Result<Value, String> {
        info!("Executing indexer_search with args: {:?}", args);

        let query = args.get("query").and_then(Value::as_str).ok_or_else(|| "Missing 'query' argument".to_string())?;

        let mut command = Command::new("bash");
        command.arg("openclaw-indexer/run.sh").arg("search").arg(query);

        if let Some(repo) = args.get("repo").and_then(Value::as_str) {
            command.arg("--repo").arg(repo);
        }
        if let Some(language) = args.get("language").and_then(Value::as_str) {
            command.arg("--language").arg(language);
        }
        if let Some(limit) = args.get("limit").and_then(Value::as_u64) {
            command.arg("--limit").arg(limit.to_string());
        }

        let output = command.output().map_err(|e| format!("Failed to execute command: {}", e))?;

        if output.status.success() {
            let stdout = String::from_utf8_lossy(&output.stdout).to_string();
            info!("Indexer search successful: {}", stdout);
            // Parse the stdout into a structured JSON array of results
            // This will require more sophisticated parsing based on the actual output format.
            // For now, returning a simple JSON object with the raw output.
            Ok(json!({ "raw_output": stdout }))
        } else {
            let stderr = String::from_utf8_lossy(&output.stderr).to_string();
            error!("Indexer search failed: {}", stderr);
            Err(format!("Indexer search failed: {}", stderr))
        }
    }
}

pub fn create_indexer_tools() -> Vec<Arc<dyn Tool>> {
    vec![
        Arc::new(IndexerSearchTool),
    ]
}

