        "indexer_search"
    }

    fn description(&self) -> &str {
        "Searches the Zeroclaw code index semantically for relevant code snippets."
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
